import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Cowork: The Complete Guide","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/claude/cowork.md","filePath":"products/ai-coding/claude/cowork.md","lastUpdated":1787048027000}'),i={name:"products/ai-coding/claude/cowork.md"};function n(r,e,l,d,c,u){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="cowork-the-complete-guide" tabindex="-1">Cowork: The Complete Guide <a class="header-anchor" href="#cowork-the-complete-guide" aria-label="Permalink to &quot;Cowork: The Complete Guide&quot;">​</a></h1><blockquote><p>Cowork is a built-in <strong>desktop agent mode</strong> in Claude Desktop that lets Claude directly read and write your local files, control applications, and execute automated tasks. It&#39;s an evolution of the claude.ai conversation mode — upgraded from &quot;helping you think&quot; to &quot;helping you do.&quot;</p></blockquote><h2 id="what-is-cowork" tabindex="-1">What Is Cowork <a class="header-anchor" href="#what-is-cowork" aria-label="Permalink to &quot;What Is Cowork&quot;">​</a></h2><p>Cowork is not chat, but a <strong>task execution agent</strong>. Key differences:</p><table tabindex="0"><thead><tr><th></th><th style="text-align:center;">Claude.ai Conversation Mode</th><th style="text-align:center;">Cowork Agent Mode</th></tr></thead><tbody><tr><td>File Access</td><td style="text-align:center;">Manual upload required</td><td style="text-align:center;">Direct read/write local files</td></tr><tr><td>Task Length</td><td style="text-align:center;">Single-turn conversation</td><td style="text-align:center;">Long-running complex tasks</td></tr><tr><td>Automation</td><td style="text-align:center;">Not supported</td><td style="text-align:center;">Supports scheduled execution</td></tr><tr><td>Output</td><td style="text-align:center;">Text/code</td><td style="text-align:center;">Excel, PPT, documents, emails, etc.</td></tr><tr><td>Multi-tasking</td><td style="text-align:center;">Serial conversations</td><td style="text-align:center;">Parallel workflow decomposition</td></tr></tbody></table><p><strong>Target Audience</strong>: Pro, Max, Team, and Enterprise paid users, requires Claude Desktop installation (macOS / Windows).</p><hr><h2 id="core-capabilities" tabindex="-1">Core Capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to &quot;Core Capabilities&quot;">​</a></h2><h3 id="direct-local-file-access" tabindex="-1">Direct Local File Access <a class="header-anchor" href="#direct-local-file-access" aria-label="Permalink to &quot;Direct Local File Access&quot;">​</a></h3><p>Claude can read and write folders you authorize, no manual upload or download needed. Typical scenarios:</p><ul><li>Organize documents in your Downloads folder</li><li>Read local CSV and generate analysis reports</li><li>Batch rename files</li><li>Read code directories and generate technical documentation</li></ul><h3 id="professional-document-generation" tabindex="-1">Professional Document Generation <a class="header-anchor" href="#professional-document-generation" aria-label="Permalink to &quot;Professional Document Generation&quot;">​</a></h3><p>Cowork has built-in document skills, directly generating and saving locally:</p><ul><li><strong>Excel spreadsheets</strong>: Data analysis, financial models, Gantt charts</li><li><strong>PowerPoint presentations</strong>: Auto-layout, embedded charts</li><li><strong>Word documents</strong>: Reports, contracts, manuals</li><li><strong>PDF</strong>: Merge, split, fill forms</li></ul><h3 id="task-decomposition-and-parallelism" tabindex="-1">Task Decomposition and Parallelism <a class="header-anchor" href="#task-decomposition-and-parallelism" aria-label="Permalink to &quot;Task Decomposition and Parallelism&quot;">​</a></h3><p>Claude breaks complex work into sub-tasks and coordinates execution. For example, &quot;analyze all meeting records from last quarter, extract key decisions, generate summary report&quot; decomposes to: read files → analyze individually → aggregate and integrate → write output file.</p><h3 id="scheduled-task-execution" tabindex="-1">Scheduled Task Execution <a class="header-anchor" href="#scheduled-task-execution" aria-label="Permalink to &quot;Scheduled Task Execution&quot;">​</a></h3><p>Create tasks that run automatically by frequency, such as daily briefings, weekly summaries, periodic file organization.</p><hr><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><h3 id="step-1-install-and-open-claude-desktop" tabindex="-1">Step 1: Install and Open Claude Desktop <a class="header-anchor" href="#step-1-install-and-open-claude-desktop" aria-label="Permalink to &quot;Step 1: Install and Open Claude Desktop&quot;">​</a></h3><p>Download links:</p><ul><li><a href="https://claude.ai/api/desktop/darwin/universal/dmg/latest/redirect" target="_blank" rel="noreferrer">macOS</a></li><li><a href="https://claude.ai/api/desktop/win32/x64/exe/latest/redirect" target="_blank" rel="noreferrer">Windows x64</a></li></ul><p>After installation, log in to your Claude Pro account.</p><h3 id="step-2-switch-to-cowork-mode" tabindex="-1">Step 2: Switch to Cowork Mode <a class="header-anchor" href="#step-2-switch-to-cowork-mode" aria-label="Permalink to &quot;Step 2: Switch to Cowork Mode&quot;">​</a></h3><p>After opening Claude Desktop, switch to the <strong>Cowork</strong> tab in the top tab bar (alongside regular chat tabs).</p><h3 id="step-3-authorize-folders" tabindex="-1">Step 3: Authorize Folders <a class="header-anchor" href="#step-3-authorize-folders" aria-label="Permalink to &quot;Step 3: Authorize Folders&quot;">​</a></h3><p>On first execution of file-related tasks, Cowork will request permission to access specific folders. Recommendations:</p><ul><li>Only authorize directories you need to operate (don&#39;t authorize entire disk)</li><li>Avoid authorizing directories containing passwords, keys, or financial credentials</li></ul><h3 id="step-4-describe-your-task" tabindex="-1">Step 4: Describe Your Task <a class="header-anchor" href="#step-4-describe-your-task" aria-label="Permalink to &quot;Step 4: Describe Your Task&quot;">​</a></h3><p>Describe the work to be completed in natural language:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me read all .docx files in ~/Downloads/meeting-notes/ folder,</span></span>
<span class="line"><span>extract &quot;action items&quot; from each file, summarize into an Excel spreadsheet,</span></span>
<span class="line"><span>save as ~/Documents/action-items.xlsx</span></span></code></pre></div><p>Claude will display an execution plan, and after confirmation, begin running.</p><hr><h2 id="scheduled-task-automation" tabindex="-1">Scheduled Task Automation <a class="header-anchor" href="#scheduled-task-automation" aria-label="Permalink to &quot;Scheduled Task Automation&quot;">​</a></h2><h3 id="⚠️-two-task-types-one-critical-difference" tabindex="-1">⚠️ Two Task Types, One Critical Difference <a class="header-anchor" href="#⚠️-two-task-types-one-critical-difference" aria-label="Permalink to &quot;⚠️ Two Task Types, One Critical Difference&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th style="text-align:center;">Desktop Scheduled Tasks</th><th style="text-align:center;">Cloud Scheduled Tasks</th></tr></thead><tbody><tr><td><strong>Runtime Environment</strong></td><td style="text-align:center;">Your computer</td><td style="text-align:center;">Anthropic cloud servers</td></tr><tr><td><strong>Runs When Computer Off?</strong></td><td style="text-align:center;">❌ Must be on</td><td style="text-align:center;">✅ Runs anytime</td></tr><tr><td><strong>Access Local Files?</strong></td><td style="text-align:center;">✅ Direct access</td><td style="text-align:center;">❌ Cloud only</td></tr><tr><td><strong>Creation Entry</strong></td><td style="text-align:center;">Cowork sidebar</td><td style="text-align:center;">claude.ai/code or /schedule</td></tr><tr><td><strong>Best For</strong></td><td style="text-align:center;">Tasks involving local files</td><td style="text-align:center;">Tasks independent of local files</td></tr></tbody></table><p><strong>Desktop tasks</strong>: Computer must be awake and Claude Desktop open. If asleep, tasks are skipped (not made up).</p><p><strong>Cloud tasks</strong>: Run on Anthropic-managed servers, available 24/7, suitable for automation that doesn&#39;t need local files.</p><h3 id="what-are-scheduled-tasks" tabindex="-1">What Are Scheduled Tasks <a class="header-anchor" href="#what-are-scheduled-tasks" aria-label="Permalink to &quot;What Are Scheduled Tasks&quot;">​</a></h3><p>Scheduled tasks are saved prompts + execution plans that can run automatically by frequency, or be triggered manually on demand.</p><h3 id="common-use-cases" tabindex="-1">Common Use Cases <a class="header-anchor" href="#common-use-cases" aria-label="Permalink to &quot;Common Use Cases&quot;">​</a></h3><ul><li><strong>Daily briefing</strong>: Summarize past 24 hours of emails and calendar events, generate today&#39;s to-do list</li><li><strong>Weekly report organization</strong>: Every Friday, organize weekly work logs into a structured report</li><li><strong>Periodic research</strong>: Daily track specific industry news, generate summary files</li><li><strong>File organization</strong>: Weekly sort and clean specified folders</li><li><strong>Data updates</strong>: Periodically pull data and update Excel reports</li></ul><h3 id="method-1-the-schedule-command" tabindex="-1">Method 1: The /schedule Command <a class="header-anchor" href="#method-1-the-schedule-command" aria-label="Permalink to &quot;Method 1: The /schedule Command&quot;">​</a></h3><p>In any Cowork task conversation, enter <code>/schedule</code>, and Claude will guide you through creation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/schedule</span></span></code></pre></div><p>Claude will ask: task name, execution frequency, whether to bind to specific folders, etc.</p><h3 id="method-2-from-the-scheduled-tasks-page" tabindex="-1">Method 2: From the Scheduled Tasks Page <a class="header-anchor" href="#method-2-from-the-scheduled-tasks-page" aria-label="Permalink to &quot;Method 2: From the Scheduled Tasks Page&quot;">​</a></h3><ol><li>Click <strong>Scheduled Tasks</strong> in the left sidebar</li><li>Click <strong>+ New Task</strong> in the top right</li><li>Fill the form:</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Task Name</td><td>Recognizable name, such as &quot;Daily Work Briefing&quot;</td></tr><tr><td>Description</td><td>Brief explanation of task purpose</td></tr><tr><td>Execution Prompt</td><td>Complete instruction Claude receives each run</td></tr><tr><td>Run Frequency</td><td>Hourly / Daily / Weekly / Workdays / Manual</td></tr><tr><td>Model Selection</td><td>Default Claude Sonnet, complex tasks can choose Opus</td></tr><tr><td>Working Folder</td><td>Optional, bind to specific directory</td></tr></tbody></table><h3 id="managing-scheduled-tasks" tabindex="-1">Managing Scheduled Tasks <a class="header-anchor" href="#managing-scheduled-tasks" aria-label="Permalink to &quot;Managing Scheduled Tasks&quot;">​</a></h3><ul><li><strong>Manual trigger</strong>: Click run button next to task to execute once immediately</li><li><strong>Pause/resume</strong>: Toggle task&#39;s enabled status</li><li><strong>View history</strong>: Click task to view past run records and outputs</li></ul><hr><h2 id="plugin-system" tabindex="-1">Plugin System <a class="header-anchor" href="#plugin-system" aria-label="Permalink to &quot;Plugin System&quot;">​</a></h2><h3 id="what-are-plugins" tabindex="-1">What Are Plugins <a class="header-anchor" href="#what-are-plugins" aria-label="Permalink to &quot;What Are Plugins&quot;">​</a></h3><p>Plugins are extension packages that bundle <strong>Skills + Connectors + Agents</strong> together. Install once to gain a complete set of specialized capabilities without configuring each individually.</p><p>For example, after installing a &quot;Financial Analysis&quot; plugin, Claude gains:</p><ul><li>Skills for reading financial statements</li><li>Connectors for specific financial APIs</li><li>Sub-agents specialized for financial analysis</li></ul><h3 id="installing-plugins" tabindex="-1">Installing Plugins <a class="header-anchor" href="#installing-plugins" aria-label="Permalink to &quot;Installing Plugins&quot;">​</a></h3><ol><li>Open Claude Desktop, switch to Cowork tab</li><li>Click <strong>Customize</strong> menu in the left sidebar</li><li>Select <strong>Browse Plugins</strong> to view available options</li><li>Click <strong>Install</strong> to complete deployment</li></ol><p>You can also upload local custom plugin files (<code>.skill</code> format).</p><h3 id="using-plugin-skills" tabindex="-1">Using Plugin Skills <a class="header-anchor" href="#using-plugin-skills" aria-label="Permalink to &quot;Using Plugin Skills&quot;">​</a></h3><p>After installing plugins, in Cowork task conversations:</p><ul><li>Type <code>/</code> to view all available skills list</li><li>Click <code>+</code> button to browse and invoke skills</li><li>Describe task directly, and Claude will automatically match appropriate skills</li></ul><h3 id="customizing-plugins" tabindex="-1">Customizing Plugins <a class="header-anchor" href="#customizing-plugins" aria-label="Permalink to &quot;Customizing Plugins&quot;">​</a></h3><p>Click the <strong>Customize</strong> button next to an installed plugin to collaborate with Claude in adjusting the plugin&#39;s prompts, skills, and connector configurations to better fit your workflow.</p><h3 id="building-your-own-plugins" tabindex="-1">Building Your Own Plugins <a class="header-anchor" href="#building-your-own-plugins" aria-label="Permalink to &quot;Building Your Own Plugins&quot;">​</a></h3><p>Cowork includes a built-in <strong>Plugin Creator</strong> plugin to guide you building from scratch:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin-create</span></span></code></pre></div><p>Follow the guide: plugin name → skill definition → connector configuration → test verification → export and share.</p><hr><h2 id="the-claude-desktop-code-tab-claude-code" tabindex="-1">The Claude Desktop Code Tab (Claude Code) <a class="header-anchor" href="#the-claude-desktop-code-tab-claude-code" aria-label="Permalink to &quot;The Claude Desktop Code Tab (Claude Code)&quot;">​</a></h2><p>Beyond Cowork, Claude Desktop has a <strong>Code tab</strong> — the graphical interface for Claude Code aimed at developers, providing more visual capabilities than the terminal CLI:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Visual Diff Review</strong></td><td>Visually review code changes, supports inline comments</td></tr><tr><td><strong>App Live Preview</strong></td><td>Start dev server, preview effects in sidebar in real time</td></tr><tr><td><strong>PR Monitoring</strong></td><td>Real-time CI status viewing, enable Auto-fix for Claude to auto-repair</td></tr><tr><td><strong>Parallel Sessions</strong></td><td>Multiple Claude instances handle different tasks simultaneously, Git worktree auto-isolation</td></tr><tr><td><strong>Dispatch</strong></td><td>Send tasks from mobile, desktop auto-creates session to execute</td></tr><tr><td><strong>Connectors</strong></td><td>Connect to external services like GitHub, Slack, Linear</td></tr><tr><td><strong>SSH Sessions</strong></td><td>Connect to dev environments on remote servers</td></tr><tr><td><strong>Cloud Sessions</strong></td><td>Start long-running tasks on Anthropic cloud (runs even when computer is off)</td></tr></tbody></table><blockquote><p>Cowork (task agent) and Code (programming agent) are two parallel tabs in Claude Desktop, serving different use cases.</p></blockquote><hr><h2 id="computer-use" tabindex="-1">Computer Use <a class="header-anchor" href="#computer-use" aria-label="Permalink to &quot;Computer Use&quot;">​</a></h2><h3 id="what-is-computer-use" tabindex="-1">What Is Computer Use <a class="header-anchor" href="#what-is-computer-use" aria-label="Permalink to &quot;What Is Computer Use&quot;">​</a></h3><p>Computer Use enables Claude to <strong>operate your computer like a human</strong> — controlling mouse, keyboard, viewing screen, thereby operating any desktop app and browser, even without API interfaces.</p><p>Typical scenarios:</p><ul><li>Search in browser, fill forms, extract information</li><li>Operate desktop software like Excel, Word</li><li>Transfer data between apps (e.g., extract data from email and fill into CRM)</li></ul><h3 id="how-to-enable" tabindex="-1">How to Enable <a class="header-anchor" href="#how-to-enable" aria-label="Permalink to &quot;How to Enable&quot;">​</a></h3><p>In Claude Desktop settings, go to <strong>Desktop App → Computer Use</strong> to enable.</p><p><strong>Note</strong>: After enabling, Claude will request separate permission before accessing each app; you can selectively authorize.</p><h3 id="security-boundaries" tabindex="-1">Security Boundaries <a class="header-anchor" href="#security-boundaries" aria-label="Permalink to &quot;Security Boundaries&quot;">​</a></h3><p>Computer Use has elevated permissions; recommendations:</p><ul><li>Carefully review Claude&#39;s operation plan before execution</li><li>Don&#39;t use in apps involving online banking, password managers, etc.</li><li>Monitor task process, can interrupt anytime</li></ul><hr><h2 id="cross-app-collaboration" tabindex="-1">Cross-App Collaboration <a class="header-anchor" href="#cross-app-collaboration" aria-label="Permalink to &quot;Cross-App Collaboration&quot;">​</a></h2><h3 id="dispatching-tasks-from-anywhere" tabindex="-1">Dispatching Tasks from Anywhere <a class="header-anchor" href="#dispatching-tasks-from-anywhere" aria-label="Permalink to &quot;Dispatching Tasks from Anywhere&quot;">​</a></h3><p>Cowork supports initiating tasks without opening Claude Desktop:</p><p><strong>Method 1</strong>: Through Claude&#39;s shortcut or global menu, send tasks to Cowork queue from any app; Claude Desktop will receive and execute in the background.</p><p><strong>Method 2 (Claude in Chrome)</strong>: After installing Chrome extension, select text on any browser page and send to Cowork with one click. Also supports directly controlling browser automation tasks from Chrome extension.</p><p><strong>Claude in Chrome connection</strong>: After enabling Chrome connector in Claude Desktop, directly control browser from desktop to complete tasks without switching windows.</p><p>Use cases:</p><ul><li>See article in browser → Select text → Send to Cowork → Claude summarizes and saves</li><li>See PR on GitHub → Directly have Cowork review code</li><li>Receive email notification → Cowork auto-extracts tasks and creates in Linear</li></ul><h3 id="claude-in-chrome-extension-working-with-cowork" tabindex="-1">Claude in Chrome Extension (Working with Cowork) <a class="header-anchor" href="#claude-in-chrome-extension-working-with-cowork" aria-label="Permalink to &quot;Claude in Chrome Extension (Working with Cowork)&quot;">​</a></h3><p>Chrome extension provides browser superpowers to Cowork:</p><ul><li><strong>Workflow recording</strong>: Demonstrate operation steps once, Claude learns and auto-repeats</li><li><strong>Scheduled tasks</strong>: Set browser tasks to auto-run daily/weekly/monthly</li><li><strong>Console log reading</strong>: Directly identify and debug issues in browser</li><li><strong>Multi-tab management</strong>: Claude can manage multiple tabs simultaneously, process information uniformly</li></ul><p>After installation, click Claude icon in Chrome toolbar to open side panel, working in sync with browsing.</p><h3 id="cross-app-workflow-examples" tabindex="-1">Cross-App Workflow Examples <a class="header-anchor" href="#cross-app-workflow-examples" aria-label="Permalink to &quot;Cross-App Workflow Examples&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Scenario: Summarize all meeting commitments from this week&#39;s emails into a calendar file</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Claude execution steps:</span></span>
<span class="line"><span>1. Access email client (Computer Use) to read this week&#39;s emails</span></span>
<span class="line"><span>2. Identify meeting info containing time, location, participants</span></span>
<span class="line"><span>3. Organize into structured data</span></span>
<span class="line"><span>4. Write to local calendar file or generate .ics file</span></span></code></pre></div><hr><h2 id="safe-usage-guide" tabindex="-1">Safe Usage Guide <a class="header-anchor" href="#safe-usage-guide" aria-label="Permalink to &quot;Safe Usage Guide&quot;">​</a></h2><p>Cowork has permission to access your local files and apps. Please understand the following security principles.</p><h3 id="anthropic-s-safeguards" tabindex="-1">Anthropic&#39;s Safeguards <a class="header-anchor" href="#anthropic-s-safeguards" aria-label="Permalink to &quot;Anthropic&#39;s Safeguards&quot;">​</a></h3><ul><li><strong>Injection attack protection</strong>: Claude is trained to identify and reject deceptive instructions from malicious content</li><li><strong>Content classification</strong>: Automatically scan untrusted content and flag potential risks</li><li><strong>Deletion protection</strong>: Must obtain your explicit permission before permanently deleting files</li><li><strong>Per-app authorization</strong>: Computer Use requests separate permission before accessing each app</li></ul><h3 id="what-you-should-do" tabindex="-1">What You Should Do <a class="header-anchor" href="#what-you-should-do" aria-label="Permalink to &quot;What You Should Do&quot;">​</a></h3><p><strong>Selective authorization</strong>: Only grant Claude access to necessary folders, avoid authorizing directories with financial information or login credentials.</p><p><strong>Monitor tasks</strong>: Watch for unexpected behavior — is Claude accessing files or websites you didn&#39;t mention?</p><p><strong>Careful with scheduled tasks</strong>:</p><ul><li>Start with simple tasks, gradually expand</li><li>Don&#39;t automate tasks involving sensitive data or irreversible operations (like sending emails, deleting files)</li><li>Manually run a few times to confirm correct results before enabling auto-scheduling</li></ul><p><strong>Limit browser access</strong>: Network content is the primary vector for prompt injection; restrict Computer Use&#39;s browser access to trusted websites.</p><p><strong>Review plugin permissions</strong>: Carefully read permission requests before installing plugins; only install plugins from trusted sources.</p><h3 id="your-responsibility-boundary" tabindex="-1">Your Responsibility Boundary <a class="header-anchor" href="#your-responsibility-boundary" aria-label="Permalink to &quot;Your Responsibility Boundary&quot;">​</a></h3><blockquote><p>You bear final responsibility for all operations Claude performs on your behalf, including published content, generated transactions, and modified data.</p></blockquote><hr><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>Q: Do I need to keep watching while Cowork tasks execute?</strong></p><p>No. You can set a task and leave; Claude will execute in the background. You&#39;ll be notified when done to view results. However, for high-risk operations (like batch deletion, sending emails), manual confirmation is recommended.</p><p><strong>Q: What if my computer is off when a scheduled task should run?</strong></p><p>The task will be skipped and run normally at the next trigger time. It won&#39;t &quot;make up&quot; missed runs (e.g., if you&#39;re away for 3 days, daily tasks won&#39;t run 3 times at once).</p><p><strong>Q: What&#39;s the difference between Cowork and Claude Code?</strong></p><table tabindex="0"><thead><tr><th></th><th style="text-align:center;">Cowork</th><th style="text-align:center;">Claude Code</th></tr></thead><tbody><tr><td>Primary Users</td><td style="text-align:center;">Non-developers/general users</td><td style="text-align:center;">Developers</td></tr><tr><td>Operation Targets</td><td style="text-align:center;">Files, apps, browsers</td><td style="text-align:center;">Codebases, terminals, Git</td></tr><tr><td>Interface</td><td style="text-align:center;">Claude Desktop GUI</td><td style="text-align:center;">Terminal/IDE</td></tr><tr><td>Automation Method</td><td style="text-align:center;">Scheduled tasks</td><td style="text-align:center;">Headless mode/CI</td></tr></tbody></table><p><strong>Q: Can plugin connectors access services behind firewalls?</strong></p><p>Standard connectors connect via Anthropic cloud services; custom connectors need to point to publicly accessible servers. Internal network services require separate configuration per network requirements docs.</p><hr><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://support.claude.com/en/articles/13345190" target="_blank" rel="noreferrer">Official Docs: Getting Started with Cowork</a></li><li><a href="https://support.claude.com/en/articles/13364135" target="_blank" rel="noreferrer">Using Cowork Safely</a></li><li><a href="https://support.claude.com/en/articles/13837440" target="_blank" rel="noreferrer">Using Plugins in Cowork</a></li><li><a href="https://support.claude.com/en/articles/13854387" target="_blank" rel="noreferrer">Scheduling Recurring Tasks</a></li><li><a href="https://support.claude.com/en/articles/13892150" target="_blank" rel="noreferrer">Cross-App Collaboration</a></li></ul>`,129)])])}const b=t(i,[["render",n]]);export{k as __pageData,b as default};
